class Solution {
    public int getCommon(int[] nums1,int[] nums2){
        int first=0,second=0;
        while(first<nums1.length&&second<nums2.length){
            if(nums1[first]==nums2[second])return nums1[first];
            if(nums1[first]<nums2[second])first++;
            else second++;
        }
        return -1;
    }
}

